function availableResource(r,candidate,ignore=''){
 if(!r||!r.enabled||r.type==='Protected')return false;
 const [a,b]=occupancy(candidate);
 if(r.type==='Private car'&&(!r.consent||new Date(r.shareStart).getTime()>a||new Date(r.shareEnd).getTime()<b))return false;
 if(S.resourceBlocks.some(x=>[x.resource,...(resource(x.resource)?.blocks||[])].some(id=>[r.id,...(r.blocks||[])].includes(id))&&a<new Date(x.end).getTime()&&new Date(x.start).getTime()<b))return false;
 let candidates=new Set([r.id,...(r.blocks||[])]);
 return !S.events.some(e=>e.id!==ignore&&e.status==='Approved'&&overlaps(candidate,e)&&claimedResources(e).some(id=>candidates.has(id)));
}

function bookingCheck(c,ignore=''){
 const conflicts=[],rules=S.bookingRules;
 if(c.space&&!availableResource(resource(c.space),c,ignore))conflicts.push('Space is unavailable for this time.');
 const space=resource(c.space);
 if(space&&Number(c.guests)>space.capacity)conflicts.push('Guest count exceeds the space capacity.');
 const blocked=new Set(space?.blocks||[]);
 const cars=S.resources.filter(r=>['Guest car','Private car'].includes(r.type)&&!blocked.has(r.id)&&availableResource(r,c,ignore));
 const bikes=S.resources.filter(r=>r.type==='Guest bike'&&!blocked.has(r.id)&&availableResource(r,c,ignore));
 if(cars.length<c.cars)conflicts.push('Only '+cars.length+' car spaces available.');
 if(bikes.length<c.bikes)conflicts.push('Only '+bikes.length+' bike spaces available.');
 const allocated=c.allocation?.length?c.allocation:null;
 if(allocated){const own=allocated.map(resource);if(new Set(allocated).size!==allocated.length||own.some(r=>!r||blocked.has(r.id)||!availableResource(r,c,ignore)))conflicts.push('A selected parking bay is unavailable.');
 if(own.filter(r=>r&&['Guest car','Private car'].includes(r.type)).length!==c.cars||own.filter(r=>r?.type==='Guest bike').length!==c.bikes)conflicts.push('Select the requested number of car and bike spaces.');}
 return {ok:!conflicts.length,conflicts,cars,bikes,allocation:allocated||[...cars.slice(0,c.cars),...bikes.slice(0,c.bikes)].map(r=>r.id)};
}

function validateBooking(d,editing=false){
 const e={...d,title:requiredText(d.title,'Event name',80),type:d.type||'Other',flat:isStaff()?d.flat:S.residentFlat,guests:finiteInt(d.guests,1,S.bookingRules.maxGuests,'Guests'),cars:finiteInt(d.cars,0,S.bookingRules.maxCars,'Car spaces'),bikes:finiteInt(d.bikes,0,S.bookingRules.maxBikes,'Bike spaces'),setup:S.bookingRules.setupMinutes,cleanup:S.bookingRules.cleanupMinutes};
 if(!flat(e.flat)?.member)fail('Choose an active member flat.');
 const start=new Date(e.start),end=new Date(e.end),now=new Date(S.referenceNow),dayLimit=new Date(now);dayLimit.setDate(dayLimit.getDate()+S.bookingRules.advanceDays);
 if(isNaN(start)||isNaN(end)||start<=now||end<=start)fail('Choose a future start and a later end time.');
 if((end-start)/3600000>S.bookingRules.maxHours)fail('Booking exceeds the maximum duration.');
 if(start>dayLimit)fail('Choose a date within '+S.bookingRules.advanceDays+' days.');
 const qs=S.bookingRules.quietStart,qe=S.bookingRules.quietEnd;
 // Common-area functions may not cross quiet hours. Parking-only reservations are exempt.
 if(e.space){const a=start.getHours()*60+start.getMinutes(),b=end.getHours()*60+end.getMinutes(),qStart=Number(qs.slice(0,2))*60+Number(qs.slice(3)),qEnd=Number(qe.slice(0,2))*60+Number(qe.slice(3));
 if(e.start.slice(0,10)!==e.end.slice(0,10)||(qStart>qEnd?(a<qEnd||b>qStart):(a<qEnd&&b>qStart)))fail('Choose a common-space time outside the quiet hours.');}
 if(!e.space&&!e.cars&&!e.bikes)fail('Choose a common space or request guest parking.');
 if(e.space&&resource(e.space)?.type!=='Common space')fail('Choose a bookable common space.');
 e.date=e.start.slice(0,10);e.notes=safeText(d.notes,500);return e;
}

