 sub.firstCredit=true;sub.rewardedAt=stamp();sub.rewardRefs=refs.slice(0,2).map(r=>r.id);const inv=firstInvoice();inv.discount=inv.amount;inv.status=inv.status==='Paid'?'Refund due':'Waived';
 sub.rewardRefs.forEach(id=>{const r=sub.referrals.find(r=>r.id===id);r.credit=true;r.creditAmount=r.flats<=10?99:r.flats<=30?149:249;r.rewardEnd=nextCycle(r.activatedDate||refDate(),'Monthly');});
